static float TRS16_relu(float x)
{
    return x > 0.0f ? x : 0.0f;
}

static float TRS16_sigmoid(float x)
{
    if (x > 15.0f)
        return 1.0f;
    if (x < -15.0f)
        return 0.0f;
    return 1.0f / (1.0f + expf(-x));
}

int TRS_score_num16_operations_with_logits(
        const TRS_NumericFeatures* f,
        float scores_out[TRS_SCORE_NUM16_N_OPERATIONS],
        float logits_out[TRS_SCORE_NUM16_N_OPERATIONS])
{
    float input[TRS16_N_FEATURES];
    float hidden[44];
    float hidden_next[44];
    float output[TRS16_N_OUTPUTS];

    /* Extract and normalize features */
    input[0] = ((float)((
                        (((double)(long long)((
                                ((double)(f->count)) > 0.0
                                        ? log2((double)(f->count))
                                        : 0.0))))
                                        < ((double)(21))
                                ? (((double)(long long)((
                                          ((double)(f->count)) > 0.0
                                                  ? log2((double)(f->count))
                                                  : 0.0))))
                                : ((double)(21))))
                - TRS16_norm_mean[0])
            / TRS16_norm_std[0];
    input[1] = ((float)(f->zero_ratio_fp) - TRS16_norm_mean[1])
            / TRS16_norm_std[1];
    input[2] = ((float)(f->delta_up_ratio_fp) - TRS16_norm_mean[2])
            / TRS16_norm_std[2];
    input[3] = ((float)(f->delta_down_ratio_fp) - TRS16_norm_mean[3])
            / TRS16_norm_std[3];
    input[4] = ((float)((
                        (double)(4294967296ULL)
                        - (double)(f->delta_down_ratio_fp)))
                - TRS16_norm_mean[4])
            / TRS16_norm_std[4];
    input[5] = ((float)(f->range_u) - TRS16_norm_mean[5]) / TRS16_norm_std[5];
    input[6] = ((float)(f->min_u) - TRS16_norm_mean[6]) / TRS16_norm_std[6];
    input[7] =
            ((float)((f->min_u == 0)) - TRS16_norm_mean[7]) / TRS16_norm_std[7];
    input[8] = ((float)(((f->min_u == 0) && (f->max_u > 255)))
                - TRS16_norm_mean[8])
            / TRS16_norm_std[8];
    input[9] = ((float)((
                        ((double)(f->cardinality_est) * (double)(4294967296ULL))
                        / (((double)(f->count)) > ((double)(1))
                                   ? ((double)(f->count))
                                   : ((double)(1)))))
                - TRS16_norm_mean[9])
            / TRS16_norm_std[9];
    input[10] = ((float)((
                         ((double)(f->pair_cardinality_est)
                          * (double)(4294967296ULL))
                         / ((((double)(f->count) - (double)(1))) > ((double)(1))
                                    ? (((double)(f->count) - (double)(1)))
                                    : ((double)(1)))))
                 - TRS16_norm_mean[10])
            / TRS16_norm_std[10];
    input[11] = ((float)(f->sorted_gap_cv_fp) - TRS16_norm_mean[11])
            / TRS16_norm_std[11];
    input[12] =
            ((float)(f->min_lb0) - TRS16_norm_mean[12]) / TRS16_norm_std[12];
    input[13] = ((float)((
                         (double)(f->delta_first_max_s)
                         - (double)(f->delta_first_min_s)))
                 - TRS16_norm_mean[13])
            / TRS16_norm_std[13];
    input[14] =
            ((float)((
                     (double)(f->cardinality_est)
                     / ((((double)(f->range_u) + (double)(1))) > ((double)(1))
                                ? (((double)(f->range_u) + (double)(1)))
                                : ((double)(1)))))
             - TRS16_norm_mean[14])
            / TRS16_norm_std[14];
    input[15] = ((float)((
                         (double)(f->d8_cardinality_est)
                         / (((((double)(f->count) * (double)(2)) - (double)(7)))
                                            > ((double)(1))
                                    ? ((((double)(f->count) * (double)(2))
                                        - (double)(7)))
                                    : ((double)(1)))))
                 - TRS16_norm_mean[15])
            / TRS16_norm_std[15];
    input[16] = ((float)((
                         (double)(f->mean_abs_delta_u_fp)
                         / (double)(4294967296ULL)))
                 - TRS16_norm_mean[16])
            / TRS16_norm_std[16];
    input[17] = ((float)((
                         (double)(f->delta_first_max_s)
                         / (((double)(f->range_s)) > ((double)(1))
                                    ? ((double)(f->range_s))
                                    : ((double)(1)))))
                 - TRS16_norm_mean[17])
            / TRS16_norm_std[17];
    input[18] =
            ((float)((
                     (((double)(1)
                       + ((((double)(f->mean_abs_delta_u_fp)
                            / (double)(4294967296ULL))
                           * (double)(f->cardinality_est))
                          / (((double)(f->range_u)) > ((double)(1))
                                     ? ((double)(f->range_u))
                                     : ((double)(1))))))
                                     > 0.0
                             ? log(((double)(1)
                                    + ((((double)(f->mean_abs_delta_u_fp)
                                         / (double)(4294967296ULL))
                                        * (double)(f->cardinality_est))
                                       / (((double)(f->range_u)) > ((double)(1))
                                                  ? ((double)(f->range_u))
                                                  : ((double)(1))))))
                             : 0.0))
             - TRS16_norm_mean[18])
            / TRS16_norm_std[18];

    /* Layer 1 */
    for (int j = 0; j < 44; j++) {
        float sum = TRS16_b1[j];
        for (int i = 0; i < 19; i++) {
            sum += input[i] * TRS16_w1[i][j];
        }
        hidden[j] = TRS16_relu(sum);
    }

    /* Layer 2 */
    for (int j = 0; j < 27; j++) {
        float sum = TRS16_b2[j];
        for (int i = 0; i < 44; i++) {
            sum += hidden[i] * TRS16_w2[i][j];
        }
        hidden_next[j] = TRS16_relu(sum);
    }

    /* Layer 3 */
    for (int j = 0; j < 24; j++) {
        float sum = TRS16_b3[j];
        for (int i = 0; i < 27; i++) {
            sum += hidden_next[i] * TRS16_w3[i][j];
        }
        hidden[j] = TRS16_relu(sum);
    }

    /* Layer 4 */
    for (int j = 0; j < 12; j++) {
        float sum = TRS16_b4[j];
        for (int i = 0; i < 24; i++) {
            sum += hidden[i] * TRS16_w4[i][j];
        }
        if (logits_out)
            logits_out[j] = sum;
        output[j] = sum;
    }

    /* Copy scores and find best, by logit: saturated scores tie */
    int best = 0;
    for (int j = 0; j < TRS16_N_OUTPUTS; j++) {
        if (scores_out) {
            scores_out[j] = TRS16_sigmoid(output[j]);
        }
        if (output[j] > output[best])
            best = j;
    }

    return best;
}

int TRS_score_num16_operations(
        const TRS_NumericFeatures* f,
        float scores_out[TRS_SCORE_NUM16_N_OPERATIONS])
{
    return TRS_score_num16_operations_with_logits(f, scores_out, NULL);
}

